/**
 * Database client configuration.
 * Coordinates with Sagar's PostgreSQL and Prisma database setup.
 *
 * When Sagar initializes Prisma and generates @prisma/client,
 * this module will instantiate and export the active PrismaClient.
 * Until the database schema is pushed by Sagar, this gracefully
 * detects availability without crashing the application.
 */

let prisma = null;

try {
  const { PrismaClient } = await import("@prisma/client");
  prisma = new PrismaClient();
} catch {
  // Prisma is not yet installed or generated by Sagar
  prisma = null;
}

export const isDatabaseReady = () => Boolean(prisma);

export default prisma;
